      // Calculate the reflected light intensity (R) for this light source
      R = calculate_reflected_light_intensity(light, surface, v, t)

      // Accumulate the light intensity (L)
      L += R * light_intensity
    }
  }

  // Calculate final surface color
  surface_color = calculate_surface_color(surface, L, R)
  return surface_color
}

// Reflected light intensity calculation function
