```csharp
using System;
using System.Web.Mvc;
using Stripe;

public class StripeController : Controller
{
    [HttpPost]
    public ActionResult CreateSubscription(SubscriptionModel model)
    {
        // Create a new Stripe customer
        var customerService = new StripeCustomerService(YOUR_STRIPE_SECRET_KEY);
        var customer = customerService.Create(new StripeCustomerCreateOptions
        {
            Email = model.CustomerEmail,
            Plan = new StripePlanCreateOptions
            {
                Id = model.ProductId,
                Amount = (long)(model.InitialAmount * 100), // Stripe requires amounts in cents
                Currency = "usd", // or "gbp", "eur", etc.
                TrialPeriodDays = model.TrialDuration
            }
        });

        // Create a new Stripe subscription
        var service = new StripeSubscriptionService(YOUR_STRIPE_SECRET_KEY);
        var subscription = service.Create(new StripeSubscriptionCreateOptions
        {
            CustomerId = customer.Id,
            Items = new StripeSubscriptionCreateOptionsItems
            {
                new StripeSubscriptionCreateOptionsItem
                {
                    Plan = model.ProductId,
                    Quantity = 1
                }
            },
            TrialFromPlan = true,
            TrialPeriodDays = model.TrialDuration
        });

        // Apply a discount to the first trial amount
        var discount = new StripeDiscountCreateOptions
        {
            Amount = (long)(model.TrialAmount * 100), // Stripe requires amounts in cents
            Currency = "usd", // or "gbp", "eur", etc.
            RedeemById = subscription.Id,
            Interval = "month", // or "year", etc.
            IntervalCount = 1
        };
        var discountService = new StripeDiscountService(YOUR_STRIPE_SECRET_KEY);
        discountService.Create(discount);

        // Return a success message
        return Json(new { success = true });
    }
}
