Voici un exemple de code en C# utilisant `HttpListener` pour créer un serveur HTTP simple qui répond avec le message "Hello" à la page "/hello" sur le port 8080 :
```csharp
using System;
using System.Net;
using System.Net.Http;
using System.Threading;

class HttpServer
{
    static void Main(string[] args)
    {
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/");
        listener.Start();

        Console.WriteLine("Serveur HTTP démarré. Attendre des requêtes...");

        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            if (request.Url.AbsolutePath == "/hello")
            {
                string response = "Hello";
                byte[] buffer = System.Text.Encoding.UTF8.GetBytes(response);
                context.Response.ContentLength64 = buffer.Length;
                context.Response.OutputStream.Write(buffer, 0, buffer.Length);
                context.Response.OutputStream.Close();
            }
            else
            {
                // Répondre avec un code d'état 404 (Not Found) pour les requêtes non reconnues
                string response = "La page demandée n'existe pas.";
                byte[] buffer = System.Text.Encoding.UTF8.GetBytes(response);
                context.Response.StatusCode = 404;
                context.Response.ContentLength64 = buffer.Length;
                context.Response.OutputStream.Write(buffer, 0, buffer.Length);
                context.Response.OutputStream.Close();
            }
        }
    }
}
```
