#include <string>
#include <thread>
#include <chrono>

int main() {
    // Create a semaphore
    boost::interprocess::interprocess_semaphore sem(0); // Initialize semaphore with 0

    // Decrement the semaphore to block the current thread
    sem waits();

    // Send a message to the child process
    std::cout << "Parent process is waiting..." << std::endl;

    // Wait 5 seconds...
    std::this_thread::sleep_for(std::chrono::seconds(5));

    // Post to the semaphore to release the blocked thread
    sem.post();

    // Increment the semaphore to release the blocked thread
    sem.release();

    return 0;
}
