```Python
import sys
from PyQt5.QtWidgets import QApplication, QMessageBox
from PyQt5.QtCore import Qt
from PyQt5.QtSql import QSqlDatabase, QSqlQuery
from PyQt5.QtQml import QQmlApplicationEngine

class TodoApp(QQmlApplicationEngine):
    def __init__(self):
        super().__init__()

        # Initialize the database
        self.db = QSqlDatabase.addDatabase('QMYSQL')
        self.db.setHostName('localhost')
        self.db.setDatabaseName('todo_app')
        self.db.setUserName('root')
        self.db.setPassword('')

        if not self.db.open():
            print(self.db.lastError().text())
            return

        # Create the view
        self.create_view()

    def create_view(self):
        # Create the QML view
        self.engine = QQmlApplicationEngine()
        self.engine.load('main.qml')

        # Create the context
        self.ctx = self.engine.rootObjects()[0].context()

        # Connect the signals
        self.ctx.setContextProperty('todoApp', self)

    def add_task(self, task_name):
        query = QSqlQuery(self.db)
        query.prepare('INSERT INTO tasks (name) VALUES (?)')
        query.bindValue(0, task_name)
        if query.exec_():
            QMessageBox.information(None, 'Success', 'Task added successfully!')
        else:
            QMessageBox.critical(None, 'Error', query.lastError().text())

    def update_task(self, task_id, new_name):
        query = QSqlQuery(self.db)
        query.prepare('UPDATE tasks SET name = ? WHERE id = ?')
        query.bindValue(0, new_name)
        query.bindValue(1, task_id)
        if query.exec_():
            QMessageBox.information(None, 'Success', 'Task updated successfully!')
        else:
            QMessageBox.critical(None, 'Error', query.lastError().text())

    def delete_task(self, task_id):
        query = QSqlQuery(self.db)
        query.prepare('DELETE FROM tasks WHERE id = ?')
        query.bindValue(0, task_id)
        if query.exec_():
            QMessageBox.information(None, 'Success', 'Task deleted successfully!')
        else:
            QMessageBox.critical(None, 'Error', query.lastError().text())

    def get_tasks(self):
        tasks = []
        query = QSqlQuery(self.db)
        query.prepare('SELECT * FROM tasks')
        if query.exec_():
            while query.next():
                task = {
                    'id': query.value(0),
                    'name': query.value(1)
                }
                tasks.append(task)
        return tasks

if __name__ == '__main__':
    app = QApplication(sys.argv)
    todo_app = TodoApp()
    sys.exit(app.exec_())
```

