Вот пример многопоточной программы на языке C++ для вычисления приближенного значения интеграла методами прямоугольников, трапеций и парабол (метод Симпсона):
```c
#include <Windows.h>
#include <iostream>
#include <thread>
#include <random>

const int N = 4; // количество потоков
const int N_ITER = 100000; // количество итераций для каждого потока
const double FUNCTION(double x) { return x * x; } // функция для интегрирования
const double A = 0; // начало интегрирования
const double B = 1; // конец интегрирования

std::mutex mtx; // мьютекс для синхронизации вывода
std::unique_lock<std::mutex> lock(mtx); // локатор мьютекса

double integrate_sequential() {
    double result = 0;
    for (int i = 0; i < N_ITER; i++) {
        result += FUNCTION((A + B) / 2 + (B - A) * (i / (double)N_ITER));
    }
    return result * (B - A);
}

double integrate_parallel() {
    double result = 0;
    std::atomic<double> sum(0); // атомарное обновление
    std::thread threads[N];

    for (int i = 0; i < N; i++) {
        threads[i] = std::thread([&sum, &i]() {
            double local_sum = 0;
            for (int j = 0; j < N_ITER; j++) {
                local_sum += FUNCTION((A + B) / 2 + (B - A) * (j / (double)N_ITER));
            }
            lock.lock();
            sum += local_sum;
            lock.unlock();
        });
    }

    for (int i = 0; i < N; i++) {
        threads[i].join();
    }

    return sum.load() * (B - A);
}

int main() {
    HANDLE mutex_handle = CreateMutex(NULL, FALSE, NULL); // создаем мьютекс
    HANDLE semaphore_handle = CreateSemaphore(NULL, 0, N, NULL); // создаем семафор

    std::thread threads[N];

    for (int i = 0; i < N; i++) {
        threads[i] = std::thread([]() {
            sleep(1); // небольшая задержка
            std::random_device rd;
            std::mt19937 mt(rd());
            std::uniform_real_distribution<double> dist(A, B);
            double local_sum = 0;
            for (int j = 0; j < N_ITER; j++) {
                local_sum += FUNCTION(dist(mt));
            }
            lock.lock();
            WriteConsoleA(GetStdHandle(STD_OUTPUT_HANDLE), (L"Thread " + std::to_string(i) + ": " + std::to_string(local_sum) + "\n").c_str(), strlen((L"Thread " + std::to_string(i) + ": " + std::to_string(local_sum) + "\n").c_str()), NULL, NULL);
            lock.unlock();
            ReleaseSemaphore(semaphore_handle, 1, NULL); //.release 1 on the semaphore
        });
    }

    for (int i = 0; i < N; i++) {
        threads[i].join();
    }

    unseen = CreateSemaphore(NULL, 0, N, NULL); // создаем семафор для главного потока

    for (int i = 0; i < N; i++) {
        WaitforSingleObject(semaphore_handle, INFINITE); // ожидаем вычислений всех потоков
    }

    ReleaseSemaphore(unseen_handle, 1, NULL); //.release 1 on the semaphore

    WriteConsoleA(GetStdHandle(STD_OUTPUT_HANDLE), (L"Sequential: " + std::to_string(integrate_sequential()) + "\n").c_str(), strlen((L"Sequential: " + std::to_string(integrate_sequential()) + "\n").c_str()), NULL, NULL);
    WriteConsoleA(GetStdHandle(STD_OUTPUT_HANDLE), (L"Parallel: " + std::to_string(integrate_parallel()) + "\n").c_str(), strlen((L"Sequential: " + std::to_string(integrate_sequential()) + "\n").c_str()), NULL, NULL);

    return 0;
}
```
