```
// components/SessionManager.js
import React, { Component } from 'react';
import { Container, AppBar, Toolbar, Typography } from '@material-ui/core';
import { GoogleLogin } from 'react-google-login';

class SessionManager extends Component {
  constructor(props) {
    super(props);
    this.state = {
      isAuthenticated: false,
      user: null,
      accessToken: null
    };
  }

  handleLogin = (response) => {
    const { accessToken } = response;
    // Send the access token to your backend to verify the user's identity
    fetch('/api/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ accessToken })
    })
      .then((response) => response.json())
      .then((data) => {
        if (data.user) {
          this.setState({
            isAuthenticated: true,
            user: data.user,
            accessToken: accessToken
          });
        } else {
          this.setState({ isAuthenticated: false });
        }
      })
      .catch((error) => console.error(error));
  };

  handleLogout = () => {
    // Clear the access token and user data
    this.setState({
      isAuthenticated: false,
      user: null,
      accessToken: null
    });
  };

  render() {
    const { isAuthenticated, user, accessToken } = this.state;

    return (
      <Container>
        <AppBar position="static">
          <Toolbar>
            <Typography variant="h6" color="inherit">
              {isAuthenticated ? `Welcome, ${user.name}` : 'Login'}
            </Typography>
          </Toolbar>
        </AppBar>
        {isAuthenticated ? (
          <Button onClick={this.handleLogout}>Logout</Button>
