  // Add some content to the page
  var Canvas := PDFFile.LastPage.GetDatastream();
  var StringStream := TMemoryStream.Create;
  StringStream.Write('Hello, World!', Length('Hello, World!'));
  StringStream.Position := 0;
  Canvas.BeginText">'+ StringStream+'</text>');
  StringStream.Free;

  // Rotate the page by 90 degrees clockwise
